css:
.chaos-terminal {
  width: 250px;
  height: 100px;
  position: relative;
  cursor: pointer;
  transform-style: preserve-3d;
}

.main-frame {
  width: 100%;
  height: 100%;
  background: linear-gradient(
      90deg,
      #000 0%,
      #fff 2%,
      #000 4%,
      #fff 6%,
      #000 8%,
      #fff 10%,
      #000 100%
    ),
    repeating-linear-gradient(0deg, #000 0px, #000 1px, #fff 1px, #fff 2px);
  border: 4px solid #000;
  position: relative;
  overflow: visible;
  transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  box-shadow:
    0 0 0 2px #fff,
    0 0 0 4px #000,
    0 0 0 6px #fff,
    0 0 0 8px #000,
    8px 8px 0 8px #00ffff,
    16px 16px 0 8px rgba(0, 0, 0, 0.8);
}

.main-frame::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: repeating-conic-gradient(
      from 0deg,
      #000 0deg,
      #000 5deg,
      #fff 5deg,
      #fff 10deg
    ),
    repeating-linear-gradient(
      45deg,
      transparent 0px,
      transparent 3px,
      #00ffff 3px,
      #00ffff 4px
    );
  opacity: 4%;
  animation: patternShift 3s linear infinite;
}

.chaos-text {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-weight: 900;
  font-size: 16px;
  color: #000;
  text-transform: uppercase;
  letter-spacing: 2px;
  z-index: 10;
  text-shadow:
    1px 1px 0 #fff,
    -1px -1px 0 #fff,
    1px -1px 0 #fff,
    -1px 1px 0 #fff,
    2px 2px 0 #00ffff;
  animation: textGlitch 2s linear infinite;
}

@keyframes textGlitch {
  0%,
  100% {
    transform: translate(-50%, -50%);
  }
  10% {
    transform: translate(-51%, -49%);
  }
  20% {
    transform: translate(-49%, -51%);
  }
  30% {
    transform: translate(-52%, -50%);
  }
  40% {
    transform: translate(-48%, -52%);
  }
  50% {
    transform: translate(-50%, -48%);
  }
  60% {
    transform: translate(-53%, -51%);
  }
  70% {
    transform: translate(-47%, -49%);
  }
  80% {
    transform: translate(-51%, -53%);
  }
  90% {
    transform: translate(-49%, -47%);
  }
}

.icon-chaos {
  position: absolute;
  top: -10px;
  left: -10px;
  width: calc(100% + 20px);
  height: calc(100% + 20px);
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 5px;
  padding: 15px;
  background: repeating-linear-gradient(
      0deg,
      #000 0px,
      #000 3px,
      #fff 3px,
      #fff 6px
    ),
    repeating-linear-gradient(90deg, #000 0px, #000 3px, #fff 3px, #fff 6px);
  border: 4px solid #000;
  transform: scale(0) rotate(180deg);
  opacity: 0;
  transition: all 0.4s cubic-bezier(0.68, -0.55, 0.265, 1.55);
  z-index: 15;
  box-shadow:
    0 0 0 2px #00ffff,
    0 0 0 4px #000,
    0 0 0 6px #fff,
    0 0 0 8px #000;
}

.icon-chaos::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: repeating-radial-gradient(
      circle at 50% 50%,
      #000 0px,
      #000 2px,
      #fff 2px,
      #fff 4px
    ),
    linear-gradient(45deg, transparent 40%, #00ffff 50%, transparent 60%);
  opacity: 0.3;
  animation: iconChaosPattern 4s linear infinite;
}

.social-unit {
  width: 100%;
  height: 100%;
  background: #fff;
  border: 2px solid #000;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  transform: scale(0) rotate(360deg);
  transition: all 0.3s cubic-bezier(0.68, -0.55, 0.265, 1.55);
  box-shadow: inset 0 0 0 1px #00ffff;
}

.social-unit::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: repeating-linear-gradient(
    45deg,
    transparent 0px,
    transparent 2px,
    #000 2px,
    #000 3px
  );
  opacity: 0.1;
}

.social-unit svg {
  width: 20px;
  height: 20px;
  fill: #000;
  transition: all 0.2s ease;
  filter: drop-shadow(1px 1px 0 #00ffff);
}

.noise-layer {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: repeating-linear-gradient(
      0deg,
      transparent 0px,
      transparent 1px,
      rgba(0, 255, 255, 0.1) 1px,
      rgba(0, 255, 255, 0.1) 2px
    ),
    repeating-linear-gradient(
      90deg,
      transparent 0px,
      transparent 1px,
      rgba(0, 0, 0, 0.1) 1px,
      rgba(0, 0, 0, 0.1) 2px
    );
  pointer-events: none;
  z-index: 20;
  animation: noiseShift 1s linear infinite;
}

@keyframes noiseShift {
  0% {
    transform: translateX(0) translateY(0);
  }
  25% {
    transform: translateX(1px) translateY(-1px);
  }
  50% {
    transform: translateX(-1px) translateY(1px);
  }
  75% {
    transform: translateX(1px) translateY(1px);
  }
  100% {
    transform: translateX(0) translateY(0);
  }
}

.chaos-terminal:hover .main-frame {
  transform: scale(0.9) rotate(5deg);
  opacity: 0.3;
  box-shadow:
    0 0 0 2px #fff,
    0 0 0 4px #000,
    0 0 0 6px #fff,
    0 0 0 8px #000,
    20px 20px 0 8px #00ffff,
    40px 40px 0 8px rgba(0, 0, 0, 0.4);
}

.chaos-terminal:hover .chaos-text {
  transform: translate(-50%, -50%) scale(0) rotate(720deg);
  opacity: 0;
}

.chaos-terminal:hover .icon-chaos {
  transform: scale(1) rotate(0deg);
  opacity: 100%;
  transition-delay: 0.2s;
}

.chaos-terminal:hover .social-unit:nth-child(1) {
  transform: scale(1) rotate(0deg);
  transition-delay: 0.1s;
}

.chaos-terminal:hover .social-unit:nth-child(2) {
  transform: scale(1) rotate(0deg);
  transition-delay: 0.1s;
}

.chaos-terminal:hover .social-unit:nth-child(3) {
  transform: scale(1) rotate(0deg);
  transition-delay: 0.1s;
}

.chaos-terminal:hover .social-unit:nth-child(4) {
  transform: scale(1) rotate(0deg);
  transition-delay: 0.1s;
}

.social-unit:hover {
  background: #00ffff;
  transform: scale(1.2) rotate(180deg) !important;
  box-shadow:
    inset 0 0 0 1px #000,
    0 0 0 2px #fff,
    0 0 0 4px #000,
    0 0 20px #00ffff;
}

.social-unit:hover svg {
  fill: #000;
  transform: scale(1.2) rotate(-180deg);
  filter: drop-shadow(1px 1px 0 #fff);
}

/* Violent click */
.chaos-terminal:active {
  animation: terminalDestroy 0.8s ease;
}

@keyframes terminalDestroy {
  0% {
    transform: scale(1) rotate(0deg);
  }
  50% {
    transform: scale(0.8) rotate(-5deg);
    filter: invert(1) hue-rotate(180deg);
  }
  100% {
    transform: scale(1) rotate(0deg);
  }
}

/* Scanlines */
.chaos-terminal::after {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: repeating-linear-gradient(
    0deg,
    transparent 0px,
    transparent 2px,
    rgba(0, 255, 255, 0.205) 2px,
    rgba(0, 255, 255, 0.394) 4px
  );
  pointer-events: none;
  z-index: 25;
  animation: scanlines 1s linear infinite;
}

@keyframes scanlines {
  0% {
    transform: translateY(0);
  }
  100% {
    transform: translateY(10px);
  }
}
